import re
from dataclasses import dataclass, field
from typing import Optional

# The date is optional: "## [Unreleased]" has no date.
HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")

# Maintainer comments, inline or spanning lines. Whitespace before the comment,
# and whitespace after it when it ends the line, is removed with it.
COMMENT = re.compile(r"[ \t]*<!--.*?-->(?:[ \t]*(?=\r?\n|\Z))?", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def parse_changelog(text):
    # Strip comments first so that a comment containing a "## " line is not
    # mistaken for a heading.
    text = COMMENT.sub("", text)
    releases = []
    current = None
    for line in text.splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                # Some other level-2 section: it ends the current release.
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] == "":
                continue
            out.append("")
        else:
            out.append(line)
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            if release.date:
                header = f"# {release.version} ({release.date})"
            else:
                header = "# Unreleased"
            body = _clean_body(release.body)
            if not body:
                return f"{header}\n"
            return f"{header}\n\n{body}\n"
    raise LookupError(version)

